import { Button, Drawer, NavList, NavItem, Divider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface SideNavMenuProps {
  onNavigate: (key: NavKey) => void;
}

const SideNavMenu = ({ onNavigate }: SideNavMenuProps) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setIsOpen(false);
  };

  return (
